ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t result = ret_error;
    LDAPMessage *search_result = NULL;
    char *search_filter = NULL;
    char *user_dn = NULL;

    if (!ldap || !conn || !conn->username || !conn->password) {
        return ret_error;
    }

    if (ldap_connect(ldap) != ret_ok) {
        return ret_error;
    }

    search_filter = build_ldap_search_filter(conn->username);
    if (!search_filter) {
        goto cleanup;
    }

    if (ldap_search_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE,
                      search_filter, NULL, 0, &search_result) != LDAP_SUCCESS) {
        goto cleanup;
    }

    if (!search_result || ldap_count_entries(ldap->handle, search_result) != 1) {
        result = ret_not_found;
        goto cleanup;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->handle, search_result);
    user_dn = ldap_get_dn(ldap->handle, entry);
    if (!user_dn) {
        goto cleanup;
    }

    if (ldap_bind_s(ldap->handle, user_dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        result = ret_not_found;
    } else {
        result = ret_ok;
    }

cleanup:
    if (search_filter) {
        free(search_filter);
    }

    if (user_dn) {
        ldap_memfree(user_dn);
    }

    if (search_result) {
        ldap_msgfree(search_result);
    }

    ldap_disconnect(ldap);
    return result;
}

ret_t validate_user_credentials(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t result = ret_error;
    LDAPMessage *search_result = NULL;
    char *user_dn = NULL;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    if (ldap_connect(ldap) != LDAP_SUCCESS) {
        return ret_error;
    }

    char filter[1024];
    snprintf(filter, sizeof(filter), "(&(objectClass=inetOrgPerson)(uid=%s))", conn->user);

    if (ldap_search_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, &search_result) != LDAP_SUCCESS) {
        goto cleanup;
    }

    int num_entries = ldap_count_entries(ldap->handle, search_result);
    if (num_entries != 1) {
        result = (num_entries == 0) ? ret_not_found : ret_error;
        goto cleanup;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->handle, search_result);
    user_dn = ldap_get_dn(ldap->handle, entry);
    if (!user_dn) {
        goto cleanup;
    }

    if (ldap_bind_s(ldap->handle, user_dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        result = ret_error;
    } else {
        result = ret_ok;
    }

cleanup:
    if (user_dn) {
        ldap_memfree(user_dn);
    }
    if (search_result) {
        ldap_msgfree(search_result);
    }
    ldap_disconnect(ldap);

    return result;
}

ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t ret = ret_error;
    LDAPMessage *result = NULL;
    LDAPMessage *entry = NULL;
    char *dn = NULL;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    if (ldap_search_s(ldap->ld, ldap->base_dn, LDAP_SCOPE_SUBTREE,
                      ldap_filter_build(conn->user), NULL, 0, &result) != LDAP_SUCCESS) {
        return ret_error;
    }

    if (ldap_count_entries(ldap->ld, result) != 1) {
        ldap_msgfree(result);
        return ret_not_found;
    }

    entry = ldap_first_entry(ldap->ld, result);
    if (!entry) {
        ldap_msgfree(result);
        return ret_error;
    }

    dn = ldap_get_dn(ldap->ld, entry);
    if (!dn) {
        ldap_msgfree(result);
        return ret_error;
    }

    if (ldap_bind_s(ldap->ld, dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        ldap_memfree(dn);
        ldap_msgfree(result);
        return ret_not_found;
    }

    ldap_memfree(dn);
    ldap_msgfree(result);
    ldap_unbind(ldap->ld);

    return ret_ok;
}

ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t ret = ret_error;
    LDAPMessage *res = NULL;
    char *search_filter = NULL;
    char *dn = NULL;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    /* Build search filter */
    search_filter = cherokee_build_ldap_filter(conn->user);
    if (!search_filter) {
        return ret_error;
    }

    /* Perform LDAP search */
    if (ldap_search_s(ldap->ld, ldap->base_dn, LDAP_SCOPE_SUBTREE, search_filter, NULL, 0, &res) != LDAP_SUCCESS) {
        free(search_filter);
        return ret_error;
    }

    if (!res) {
        free(search_filter);
        return ret_not_found;
    }

    /* Check for exactly one entry */
    if (ldap_count_entries(ldap->ld, res) != 1) {
        ldap_msgfree(res);
        free(search_filter);
        return ret_not_found;
    }

    /* Get DN of the user */
    dn = ldap_get_dn(ldap->ld, res);
    if (!dn) {
        ldap_msgfree(res);
        free(search_filter);
        return ret_error;
    }

    /* Bind as the user to validate the password */
    if (ldap_bind_s(ldap->ld, dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        ldap_memfree(dn);
        ldap_msgfree(res);
        free(search_filter);
        return ret_not_found;
    }

    ret = ret_ok;

    /* Cleanup */
    ldap_memfree(dn);
    ldap_msgfree(res);
    free(search_filter);

    return ret;
}

ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    const char *user = conn->user;
    const char *password = conn->password;
    LDAPMessage *result = NULL;
    LDAPMessage *entry = NULL;
    char *dn = NULL;
    int rc;
    ret_t ret = ret_error;

    if (!user || !password) {
        return ret_error;
    }

    if (ldap_bind_s(ldap->ld, NULL, NULL, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        return ret_error;
    }

    char filter[1024];
    snprintf(filter, sizeof(filter), "(&(objectClass=person)(uid=%s))", user);

    if (ldap_search_ext_s(ldap->ld, ldap->base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, NULL, NULL, NULL, &result) != LDAP_SUCCESS) {
        goto cleanup;
    }

    if ((entry = ldap_first_entry(ldap->ld, result)) == NULL) {
        ret = ret_not_found;
        goto cleanup;
    }

    if ((dn = ldap_get_dn(ldap->ld, entry)) == NULL) {
        goto cleanup;
    }

    if (ldap_bind_s(ldap->ld, dn, password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        ret = ret_not_found;
    } else {
        ret = ret_ok;
    }

cleanup:
    if (result) {
        ldap_msgfree(result);
    }
    if (dn) {
        ldap_memfree(dn);
    }

    ldap_unbind(ldap->ld);

    return ret;
}
